#import "CloudClipboardWindowController.h"
#import "CloudClipboardClient.h"
@implementation MSIMECloudClipboardWindowController { NSString *_token; NSTextView *_editor; NSTextField *_search; NSTextField *_status; }
+ (instancetype)sharedController { static MSIMECloudClipboardWindowController *c; static dispatch_once_t once; dispatch_once(&once, ^{ c=[self new]; }); return c; }
- (void)showWithToken:(NSString *)token { _token=[token copy]; if(!self.window){self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,480,300) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];self.window.title=@"云剪贴板";} _editor=[[NSTextView alloc]initWithFrame:NSMakeRect(20,130,440,120)]; _search=[[NSTextField alloc]initWithFrame:NSMakeRect(20,95,300,24)]; _search.placeholderString=@"搜索云端历史"; NSButton *refresh=[NSButton buttonWithTitle:@"刷新" target:self action:@selector(refresh:)];refresh.frame=NSMakeRect(330,92,70,30); NSButton *upload=[NSButton buttonWithTitle:@"上传明确选择的文本" target:self action:@selector(upload:)];upload.frame=NSMakeRect(20,50,180,32); _status=[[NSTextField alloc]initWithFrame:NSMakeRect(20,20,440,24)];_status.editable=NO;_status.bezeled=NO;_status.drawsBackground=NO; NSView*v=[NSView new];v.frame=NSMakeRect(0,0,480,300);for(NSView*x in @[_editor,_search,refresh,upload,_status])[v addSubview:x];self.window.contentView=v;[self.window center];[self showWindow:nil];[NSApp activateIgnoringOtherApps:YES];[self refresh:nil]; }
- (void)upload:(id)sender { (void)sender; NSString *text=_editor.string;if(!text.length||text.length>4000)return;MSIMEAddCloudClipboard(text,_token,^(__unused NSData*d,NSInteger s,__unused NSError*e){if(s>=200&&s<300){self->_editor.string=@"";[self refresh:nil];}}); }
- (void)refresh:(id)sender { (void)sender;NSString *q=_search.stringValue?:@"";MSIMEFetchCloudClipboard(q,_token,^(NSData*d,NSInteger s,__unused NSError*e){(void)d; self->_status.stringValue=s>=200&&s<300?[NSString stringWithFormat:@"已刷新云端历史（%@）",q]:@"刷新失败";}); }
@end
